-- Complete every field in the three seeded Lagos City Polytechnic demo templates.
-- These are tester guides based on common project conventions, not official institutional rules.
do $$ declare inst uuid; begin select id into inst from public.institutions where lower(name)='lagos city polytechnic' limit 1;
update public.institution_templates set specification_defaults=$json${"fullName":"Demo Student","matricNumber":"LCP/DEMO/2026/001","institution":"Lagos City Polytechnic","faculty":"School of Business Studies","department":"Business Administration","degree":"HND","supervisor":"Dr. Demo Supervisor","submissionMonth":"October","submissionYear":"2026","projectTitle":"The Impact of Digital Payment Systems on Small Business Performance in Lagos","projectType":"Research Study","subjectArea":"Business administration and digital finance","problemStatement":"Small businesses face payment friction, reconciliation delays and limited transaction visibility.","aimObjectives":"To assess the effect of digital payment adoption on transaction efficiency and business performance.","expectedOutcome":"A documented analysis with practical recommendations for improving digital payment adoption.","topicApproved":true,"hasPrescribedFormat":"Yes","preliminaryPages":"Title page, certification, dedication, acknowledgement, abstract and table of contents.","institutionStructure":"Five chapters: introduction, literature review, methodology, results and discussion, conclusion and recommendations.","standardsBodies":"Use relevant Nigerian business, accounting and data-protection guidance where applicable.","fontFamily":"Times New Roman","bodyFontSize":"12","lineSpacing":"2.0","alignment":"Justified","marginLeft":"1.5","marginRight":"1","marginTop":"1","marginBottom":"1","preliminaryNumbering":"Roman numerals","chapterNumbering":"Arabic numerals","minPages":55,"targetPages":60,"maxPages":70,"countPrelim":false,"countReferences":false,"chapterCount":"5","mandatorySubsections":"Number headings and subheadings consistently throughout the five chapters.","citationStyle":"APA 7th","minReferences":25,"sourceRequirements":"Use credible recent academic sources, textbooks, official reports and peer-reviewed literature.","methodology":"Quantitative survey design with descriptive and inferential analysis.","technologies":"Microsoft Excel, SPSS or equivalent analysis software.","scope":"Selected small businesses operating within Lagos State.","dataCollectionMethod":"Structured questionnaire administered to sampled respondents.","analysisMethod":"Descriptive statistics and appropriate hypothesis testing.","hasRealData":"No","availableData":"No real dataset supplied; use clearly labelled synthetic demo data only for tester preview.","resultRequirements":"Include summary tables, charts and interpretation of findings.","testingRequirements":"Check consistency of sample size, tables, calculations and conclusions.","appendices":["Questionnaire","Interview Questions","Reference Tables"],"otherAppendices":"Consent or supporting instruments where applicable.","presentationRequired":true,"slideCount":"15-20","presentationStyle":"Academic defence","presentationGuideRequired":true,"specialInstructions":"Demo template for platform testing. Verify institutional requirements before production use.","doNotChange":"Approved title, study scope, required chapter structure and agreed citation style.","otherNotes":"Use clear academic language and preserve the student approved requirements."}$json$::jsonb,updated_at=now() where institution_id=inst and name='Lagos City Polytechnic — HND Business Administration Research';
update public.institution_templates set specification_defaults=$json${"fullName":"Demo Student","matricNumber":"LCP/DEMO/2026/002","institution":"Lagos City Polytechnic","faculty":"School of Engineering / Technology","department":"Computer Science","degree":"HND","supervisor":"Engr. Demo Supervisor","submissionMonth":"November","submissionYear":"2026","projectTitle":"Design and Implementation of a Web-Based Student Project Management System","projectType":"Software Development","subjectArea":"Web application development, database systems and user experience","problemStatement":"Manual project tracking can make assignment, review and delivery difficult to coordinate.","aimObjectives":"To design and implement a secure web-based system for managing student project workflows.","expectedOutcome":"A working responsive application with authentication, project tracking, notifications and reporting.","topicApproved":true,"hasPrescribedFormat":"Yes","preliminaryPages":"Title page, certification, dedication, acknowledgement, abstract and table of contents.","institutionStructure":"Five chapters supported by system analysis, design, implementation, testing and documentation sections.","standardsBodies":"Apply sound software engineering, security and data-protection practices.","fontFamily":"Times New Roman","bodyFontSize":"12","lineSpacing":"1.5","alignment":"Justified","marginLeft":"1.5","marginRight":"1","marginTop":"1","marginBottom":"1","preliminaryNumbering":"Roman numerals","chapterNumbering":"Arabic numerals","minPages":65,"targetPages":70,"maxPages":80,"countPrelim":false,"countReferences":false,"chapterCount":"5","mandatorySubsections":"Requirements analysis, architecture, database design, implementation, testing and evaluation.","citationStyle":"IEEE","minReferences":20,"sourceRequirements":"Use recent peer-reviewed computing literature, official technical documentation and credible standards.","methodology":"Iterative software development methodology with requirements analysis, system design, implementation and functional testing.","technologies":"HTML, CSS, JavaScript, relational database and Git.","scope":"A responsive student project management workflow for a controlled institutional environment.","dataCollectionMethod":"Requirements gathered through structured stakeholder interviews and workflow observation.","analysisMethod":"Functional testing, usability checks and comparative evaluation against stated requirements.","hasRealData":"No","availableData":"No real institutional dataset supplied for this demo template.","resultRequirements":"Include architecture diagrams, database schema, interface screenshots, test cases and evaluation results.","testingRequirements":"Test authentication, role access, CRUD operations, validation, responsiveness and error handling.","appendices":["Test Log","Code Listing","Reference Tables"],"otherAppendices":"API or database notes where necessary.","presentationRequired":true,"slideCount":"15-20","presentationStyle":"Minimal professional","presentationGuideRequired":true,"specialInstructions":"Demo template for tester use. Technology choices must be validated for each real project.","doNotChange":"Approved project scope, core requirements and agreed technology constraints unless the supervisor approves a change.","otherNotes":"Keep screenshots and implementation evidence aligned with the final tested build."}$json$::jsonb,updated_at=now() where institution_id=inst and name='Lagos City Polytechnic — HND Computer Science Software Project';
update public.institution_templates set specification_defaults=$json${"fullName":"Demo Student","matricNumber":"LCP/DEMO/2026/003","institution":"Lagos City Polytechnic","faculty":"School of Engineering / Technology","department":"Electrical / Electronics Engineering","degree":"ND","supervisor":"Engr. Demo Supervisor","submissionMonth":"September","submissionYear":"2026","projectTitle":"Design and Construction of a Regulated DC Power Supply","projectType":"Design & Construction","subjectArea":"Power electronics, circuit design and regulated DC supply systems","problemStatement":"Unregulated DC sources can produce unstable voltage unsuitable for sensitive electronic circuits.","aimObjectives":"To design, construct and test a regulated DC power supply meeting defined voltage and load requirements.","expectedOutcome":"A functional tested prototype supported by calculations, circuit diagrams and performance measurements.","topicApproved":true,"hasPrescribedFormat":"Yes","preliminaryPages":"Title page, certification, dedication, acknowledgement, abstract and table of contents.","institutionStructure":"Five chapters covering introduction, review, design and methodology, construction and testing, conclusion and recommendations.","standardsBodies":"Observe appropriate electrical safety practices and applicable technical standards.","fontFamily":"Times New Roman","bodyFontSize":"12","lineSpacing":"1.5","alignment":"Justified","marginLeft":"1.5","marginRight":"1","marginTop":"1","marginBottom":"1","preliminaryNumbering":"Roman numerals","chapterNumbering":"Arabic numerals","minPages":45,"targetPages":50,"maxPages":60,"countPrelim":false,"countReferences":false,"chapterCount":"5","mandatorySubsections":"Design calculations, component selection, circuit diagram, construction procedure, measurements, testing and discussion.","citationStyle":"IEEE","minReferences":15,"sourceRequirements":"Use electronics textbooks, manufacturer datasheets, credible technical references and applicable standards.","methodology":"Design-build-test methodology with circuit calculations, component selection, prototype construction and measured validation.","technologies":"Circuit simulation, multimeter, oscilloscope where available and technical drawing tools.","scope":"Design and test a low-voltage regulated DC supply for specified laboratory loads.","dataCollectionMethod":"Bench measurements of input voltage, output voltage, ripple and load behaviour.","analysisMethod":"Calculated versus measured values with error percentage and performance discussion.","hasRealData":"No","availableData":"No real laboratory dataset supplied; tester may enter measured values during actual project preparation.","resultRequirements":"Include circuit diagrams, component tables, calculations, photographs, measurement tables and performance charts.","testingRequirements":"Verify output regulation, load response, polarity, component ratings and electrical safety.","appendices":["Test Log","Bill of Materials","Technical Drawings","Reference Tables"],"otherAppendices":"Datasheets for major components.","presentationRequired":true,"slideCount":"10-15","presentationStyle":"Academic defence","presentationGuideRequired":true,"specialInstructions":"Demo template for tester use. Validate component ratings and safety requirements before real construction.","doNotChange":"Approved design objective, safety constraints and agreed output specification unless supervisor-approved.","otherNotes":"All measured results must be traceable to the actual prototype during a real project."}$json$::jsonb,updated_at=now() where institution_id=inst and name='Lagos City Polytechnic — ND Electrical/Electronics Design Project'; end $$;
